/**
 * Thread-safe LRU cache with TTL expiration.
 *
 * "Thread-safe" in the JS context means safe for concurrent async access:
 * an internal mutex (promise chain) serialises mutating operations so that
 * overlapping get/set calls never corrupt internal state.
 *
 * @param {object} options
 * @param {number} options.maxSize - Maximum number of entries (must be > 0)
 * @param {number} options.ttlMs   - Time-to-live in milliseconds (must be > 0)
 */
function validate_schema({ maxSize, ttlMs } = {}) {
  if (!Number.isFinite(maxSize) || maxSize <= 0) {
    throw new RangeError('maxSize must be a positive number');
  }
  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
    throw new RangeError('ttlMs must be a positive number');
  }

  // Doubly-linked list node
  class Node {
    constructor(key, value, expiresAt) {
      this.key = key;
      this.value = value;
      this.expiresAt = expiresAt;
      this.prev = null;
      this.next = null;
    }
  }

  const map = new Map(); // key -> Node
  let head = null; // most-recently used
  let tail = null; // least-recently used
  let size = 0;

  // Mutex: a promise chain that serialises async mutations
  let mutex = Promise.resolve();

  function withLock(fn) {
    mutex = mutex.then(fn, fn);
    return mutex;
  }

  // ── Linked-list helpers ────────────────────────────────────────────────

  function moveToFront(node) {
    if (node === head) return;
    detach(node);
    node.prev = null;
    node.next = head;
    if (head) head.prev = node;
    head = node;
    if (!tail) tail = node;
  }

  function detach(node) {
    if (node.prev) node.prev.next = node.next;
    if (node.next) node.next.prev = node.prev;
    if (node === head) head = node.next;
    if (node === tail) tail = node.prev;
    node.prev = null;
    node.next = null;
  }

  function pushFront(node) {
    node.next = head;
    if (head) head.prev = node;
    head = node;
    if (!tail) tail = node;
    size++;
  }

  function removeTail() {
    if (!tail) return null;
    const node = tail;
    detach(node);
    map.delete(node.key);
    size--;
    return node;
  }

  function isExpired(node) {
    return Date.now() > node.expiresAt;
  }

  // ── Public API (all operations are serialised via the mutex) ───────────

  /**
   * Retrieve a value. Returns undefined on miss or expiry.
   * Moves the entry to the head (most-recently used).
   */
  function get(key) {
    return withLock(() => {
      const node = map.get(key);
      if (!node) return undefined;
      if (isExpired(node)) {
        detach(node);
        map.delete(node.key);
        size--;
        return undefined;
      }
      moveToFront(node);
      return node.value;
    });
  }

  /**
   * Insert or update a value. Evicts the least-recently used entry
   * when the cache is full.
   */
  function set(key, value) {
    return withLock(() => {
      const now = Date.now();
      const existing = map.get(key);
      if (existing) {
        existing.value = value;
        existing.expiresAt = now + ttlMs;
        moveToFront(existing);
        return;
      }
      if (size >= maxSize) {
        removeTail();
      }
      const node = new Node(key, value, now + ttlMs);
      map.set(key, node);
      pushFront(node);
    });
  }

  /**
   * Check whether a non-expired entry exists.
   */
  function has(key) {
    return withLock(() => {
      const node = map.get(key);
      if (!node) return false;
      if (isExpired(node)) {
        detach(node);
        map.delete(node.key);
        size--;
        return false;
      }
      return true;
    });
  }

  /**
   * Delete an entry. Returns true if it existed.
   */
  function del(key) {
    return withLock(() => {
      const node = map.get(key);
      if (!node) return false;
      detach(node);
      map.delete(node.key);
      size--;
      return true;
    });
  }

  /**
   * Remove all expired entries.
   */
  function purge() {
    return withLock(() => {
      let removed = 0;
      // Walk from tail (oldest) toward head
      let node = tail;
      while (node) {
        const prev = node.prev;
        if (isExpired(node)) {
          detach(node);
          map.delete(node.key);
          size--;
          removed++;
        }
        node = prev;
      }
      return removed;
    });
  }

  /**
   * Current number of live (non-expired) entries.
   */
  function count() {
    return withLock(() => size);
  }

  /**
   * Remove all entries.
   */
  function clear() {
    return withLock(() => {
      map.clear();
      head = null;
      tail = null;
      size = 0;
    });
  }

  return { get, set, has, del, purge, count, clear };
}

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(condition, desc) {
    if (condition) {
      passed++;
      console.log(`  PASS: ${desc}`);
    } else {
      failed++;
      console.error(`  FAIL: ${desc}`);
    }
  }

  async function assertRejects(fn, desc) {
    try {
      await fn();
      failed++;
      console.error(`  FAIL: ${desc} (did not throw)`);
    } catch {
      passed++;
      console.log(`  PASS: ${desc}`);
    }
  }

  function sleep(ms) {
    return new Promise((r) => setTimeout(r, ms));
  }

  async function suite() {
    // ── Constructor validation ────────────────────────────────────────────

    console.log('\n=== Constructor ===');
    assertRejects(() => validate_schema({}), 'missing options throws');
    assertRejects(() => validate_schema({ maxSize: 0, ttlMs: 1000 }), 'maxSize 0 throws');
    assertRejects(() => validate_schema({ maxSize: -1, ttlMs: 1000 }), 'negative maxSize throws');
    assertRejects(() => validate_schema({ maxSize: 10, ttlMs: 0 }), 'ttlMs 0 throws');
    assertRejects(() => validate_schema({ maxSize: 10, ttlMs: -5 }), 'negative ttlMs throws');

    const ok = validate_schema({ maxSize: 3, ttlMs: 1000 });
    assert(typeof ok.get === 'function', 'returns object with get');
    assert(typeof ok.set === 'function', 'returns object with set');

    // ── Basic get/set ─────────────────────────────────────────────────────

    console.log('\n=== Basic get / set ===');
    const cache = validate_schema({ maxSize: 3, ttlMs: 5000 });

    await cache.set('a', 1);
    await cache.set('b', 2);
    await cache.set('c', 3);

    assert((await cache.get('a')) === 1, 'get a => 1');
    assert((await cache.get('b')) === 2, 'get b => 2');
    assert((await cache.get('c')) === 3, 'get c => 3');
    assert((await cache.get('d')) === undefined, 'get missing => undefined');

    // ── Update existing key ───────────────────────────────────────────────

    console.log('\n=== Update ===');
    await cache.set('a', 10);
    assert((await cache.get('a')) === 10, 'updated a => 10');

    // ── LRU eviction ─────────────────────────────────────────────────────

    console.log('\n=== LRU eviction ===');
    const lru = validate_schema({ maxSize: 2, ttlMs: 10000 });
    await lru.set('x', 1);
    await lru.set('y', 2);
    // Cache full. Inserting z should evict x (least recently used).
    await lru.set('z', 3);
    assert((await lru.get('x')) === undefined, 'x evicted');
    assert((await lru.get('y')) === 2, 'y still present');
    assert((await lru.get('z')) === 3, 'z present');

    // Access y, then insert w — z should be evicted (y is now MRU).
    await lru.get('y');
    await lru.set('w', 4);
    assert((await lru.get('z')) === undefined, 'z evicted after y access');
    assert((await lru.get('y')) === 2, 'y survived');
    assert((await lru.get('w')) === 4, 'w present');

    // ── TTL expiration ───────────────────────────────────────────────────

    console.log('\n=== TTL expiration ===');
    const ttl = validate_schema({ maxSize: 5, ttlMs: 100 });
    await ttl.set('exp', 'alive');
    assert((await ttl.get('exp')) === 'alive', 'value alive before TTL');
    await sleep(150);
    assert((await ttl.get('exp')) === undefined, 'value expired after TTL');

    // ── TTL refresh on update ─────────────────────────────────────────────

    console.log('\n=== TTL refresh on update ===');
    const refresh = validate_schema({ maxSize: 5, ttlMs: 100 });
    await refresh.set('r', 1);
    await sleep(80);
    await refresh.set('r', 2); // refresh TTL
    await sleep(80);
    assert((await refresh.get('r')) === 2, 'value alive after TTL refresh');
    await sleep(80);
    assert((await refresh.get('r')) === undefined, 'value expired after full TTL');

    // ── has() ─────────────────────────────────────────────────────────────

    console.log('\n=== has ===');
    const h = validate_schema({ maxSize: 3, ttlMs: 100 });
    await h.set('a', 1);
    assert((await h.has('a')) === true, 'has existing key');
    assert((await h.has('z')) === false, 'has missing key');
    await sleep(150);
    assert((await h.has('a')) === false, 'has expired key');

    // ── del() ─────────────────────────────────────────────────────────────

    console.log('\n=== del ===');
    const d = validate_schema({ maxSize: 3, ttlMs: 5000 });
    await d.set('a', 1);
    assert((await d.del('a')) === true, 'del existing returns true');
    assert((await d.get('a')) === undefined, 'del removes entry');
    assert((await d.del('a')) === false, 'del missing returns false');

    // ── purge() ───────────────────────────────────────────────────────────

    console.log('\n=== purge ===');
    const p = validate_schema({ maxSize: 10, ttlMs: 100 });
    await p.set('a', 1);
    await p.set('b', 2);
    await p.set('c', 3);
    await sleep(150);
    await p.set('d', 4); // d is fresh
    const removed = await p.purge();
    assert(removed === 3, `purge removed 3 expired entries (got ${removed})`);
    assert((await p.count()) === 1, 'only fresh entry remains');
    assert((await p.get('d')) === 4, 'fresh entry survived purge');

    // ── count() ───────────────────────────────────────────────────────────

    console.log('\n=== count ===');
    const c = validate_schema({ maxSize: 5, ttlMs: 5000 });
    assert((await c.count()) === 0, 'empty cache count is 0');
    await c.set('a', 1);
    await c.set('b', 2);
    assert((await c.count()) === 2, 'count after 2 inserts');
    await c.del('a');
    assert((await c.count()) === 1, 'count after delete');

    // ── clear() ───────────────────────────────────────────────────────────

    console.log('\n=== clear ===');
    const cl = validate_schema({ maxSize: 5, ttlMs: 5000 });
    await cl.set('a', 1);
    await cl.set('b', 2);
    await cl.clear();
    assert((await cl.count()) === 0, 'clear empties cache');
    assert((await cl.get('a')) === undefined, 'cleared entries are gone');

    // ── maxSize = 1 ──────────────────────────────────────────────────────

    console.log('\n=== maxSize = 1 ===');
    const one = validate_schema({ maxSize: 1, ttlMs: 5000 });
    await one.set('only', 'first');
    assert((await one.get('only')) === 'first', 'single entry works');
    await one.set('new', 'second');
    assert((await one.get('only')) === undefined, 'old entry evicted');
    assert((await one.get('new')) === 'second', 'new entry present');

    // ── Large cache ───────────────────────────────────────────────────────

    console.log('\n=== Large cache (1000 entries) ===');
    const big = validate_schema({ maxSize: 1000, ttlMs: 60000 });
    for (let i = 0; i < 1000; i++) {
      await big.set(`k${i}`, i);
    }
    assert((await big.count()) === 1000, '1000 entries inserted');
    assert((await big.get('k0')) === 0, 'first entry accessible');
    assert((await big.get('k999')) === 999, 'last entry accessible');
    await big.set('overflow', 'evict');
    assert((await big.count()) === 1000, 'still at maxSize after overflow');
    assert((await big.get('k0')) === undefined, 'LRU entry evicted');

    // ── Overwrite resets TTL ──────────────────────────────────────────────

    console.log('\n=== Overwrite resets TTL ===');
    const ow = validate_schema({ maxSize: 5, ttlMs: 100 });
    await ow.set('key', 'v1');
    await sleep(80);
    await ow.set('key', 'v2');
    await sleep(80);
    assert((await ow.get('key')) === 'v2', 'overwritten value survives past original TTL');

    // ── Concurrent access (async safety) ─────────────────────────────────

    console.log('\n=== Concurrent access ===');
    const conc = validate_schema({ maxSize: 100, ttlMs: 5000 });
    const promises = [];
    for (let i = 0; i < 50; i++) {
      promises.push(conc.set(`c${i}`, i));
    }
    await Promise.all(promises);
    assert((await conc.count()) === 50, '50 concurrent sets all applied');

    // Interleaved get/set
    const mixed = [];
    for (let i = 0; i < 50; i++) {
      mixed.push(conc.get(`c${i}`));
      mixed.push(conc.set(`c${i}`, i * 10));
    }
    await Promise.all(mixed);
    assert((await conc.get('c0')) === 0, 'concurrent get/set consistent (c0)');
    assert((await conc.get('c49')) === 490, 'concurrent get/set consistent (c49)');

    // ── Non-string keys ──────────────────────────────────────────────────

    console.log('\n=== Non-string keys ===');
    const ns = validate_schema({ maxSize: 5, ttlMs: 5000 });
    const objKey = { id: 1 };
    await ns.set(objKey, 'object value');
    assert((await ns.get(objKey)) === 'object value', 'object key works');

    await ns.set(42, 'number key');
    assert((await ns.get(42)) === 'number key', 'number key works');

    // ── Edge: empty string key ────────────────────────────────────────────

    console.log('\n=== Empty string key ===');
    const ek = validate_schema({ maxSize: 3, ttlMs: 5000 });
    await ek.set('', 'empty');
    assert((await ek.get('')) === 'empty', 'empty string key works');

    // ── Edge: undefined / null values ─────────────────────────────────────

    console.log('\n=== undefined / null values ===');
    const nv = validate_schema({ maxSize: 3, ttlMs: 5000 });
    await nv.set('undef', undefined);
    await nv.set('nul', null);
    // get returns undefined for both missing and stored-undefined;
    // has() distinguishes them.
    assert((await nv.has('undef')) === true, 'stored undefined is present');
    assert((await nv.has('nul')) === true, 'stored null is present');
    assert((await nv.get('nul')) === null, 'stored null retrieved as null');

